"""Offline tests for mirofish_requirements.py. The block format follows real `uv export` output (checked 2026-10-24)."""
import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(__file__))
import mirofish_requirements as mq  # noqa: E402

H = 'a' * 64
EXPORT = f'''# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-emit-project
anyio==4.9.0 \\
    --hash=sha256:{H} \\
    --hash=sha256:{'b' * 64}
    # via httpx
camel-oasis==0.2.5 \\
    --hash=sha256:{'c' * 64}
    # via mirofish-backend
nvidia-cublas-cu12==12.8.4.1 ; platform_machine == 'x86_64' and sys_platform == 'linux' \\
    --hash=sha256:{'d' * 64}
    # via
    #   nvidia-cudnn-cu12
    #   torch
nvidia-cudnn-cu12==9.10.2.21 ; platform_machine == 'x86_64' and sys_platform == 'linux' \\
    --hash=sha256:{'e' * 64}
    # via torch
requests==2.32.5 \\
    --hash=sha256:{'f' * 64}
    # via camel-ai
torch==2.9.1 \\
    --hash=sha256:{'1' * 64} \\
    --hash=sha256:{'2' * 64}
    # via sentence-transformers
triton==3.5.1 ; platform_machine == 'x86_64' and sys_platform == 'linux' \\
    --hash=sha256:{'3' * 64}
    # via torch
zep-cloud==3.25.0 \\
    --hash=sha256:{'4' * 64}
    # via mirofish-backend
'''


class DropGpuTests(unittest.TestCase):
    def test_drops_torch_triton_and_nvidia_blocks_whole_and_keeps_every_other_hash(self):
        text, dropped, version = mq.drop_gpu_packages(EXPORT)
        self.assertEqual(version, '2.9.1')
        self.assertEqual(dropped, ['nvidia-cublas-cu12', 'nvidia-cudnn-cu12', 'torch', 'triton'])
        for name in ('anyio==4.9.0', 'camel-oasis==0.2.5', 'requests==2.32.5', 'zep-cloud==3.25.0'):
            self.assertIn(name, text)
        for gone in ('nvidia', 'triton', 'torch==', 'sentence-transformers', f'sha256:{"1" * 64}', f'sha256:{"d" * 64}', f'sha256:{"3" * 64}'):
            self.assertNotIn(gone, text)
        for kept in (H, 'b' * 64, 'c' * 64, 'f' * 64, '4' * 64):
            self.assertIn(f'--hash=sha256:{kept}', text)

    def test_a_kept_block_keeps_its_own_hash_lines_and_via_comments(self):
        text, _, _ = mq.drop_gpu_packages(EXPORT)
        self.assertIn(f'anyio==4.9.0 \\\n    --hash=sha256:{H} \\\n    --hash=sha256:{"b" * 64}\n    # via httpx\n', text)

    def test_the_header_comments_survive(self):
        self.assertTrue(mq.drop_gpu_packages(EXPORT)[0].startswith('# This file was autogenerated by uv'))

    def test_refuses_when_the_lock_has_no_torch(self):
        with self.assertRaises(mq.RequirementsError):
            mq.drop_gpu_packages(f'anyio==4.9.0 \\\n    --hash=sha256:{H}\n')

    def test_a_package_that_merely_starts_with_torch_is_not_dropped(self):
        text, dropped, _ = mq.drop_gpu_packages(EXPORT + f'torchvision==0.24.1 \\\n    --hash=sha256:{"5" * 64}\n')
        self.assertIn('torchvision==0.24.1', text)  # a different package; the GPU rule is by exact name
        self.assertNotIn('torchvision', dropped)


class TorchCpuTests(unittest.TestCase):
    def test_pins_the_cpu_build_of_the_locked_version_by_hash(self):
        self.assertEqual(mq.torch_cpu_requirement('2.9.1', H), f'torch==2.9.1+cpu \\\n    --hash=sha256:{H}\n')

    def test_refuses_a_missing_or_malformed_hash_or_version(self):
        for version, sha in (('2.9.1', ''), ('2.9.1', 'abc'), ('2.9.1', 'G' * 64), ('latest', H), ('2.9.1; rm -rf /', H)):
            with self.assertRaises(mq.RequirementsError, msg=f'{version!r} {sha!r}'):
                mq.torch_cpu_requirement(version, sha)


class CliTests(unittest.TestCase):
    def test_writes_both_files_and_reports(self):
        with tempfile.TemporaryDirectory() as tmp:
            export = os.path.join(tmp, 'export.txt')
            with open(export, 'w') as handle:
                handle.write(EXPORT)
            code = mq.main([export, '--torch-cpu-sha256', H, '--out-main', os.path.join(tmp, 'm.txt'), '--out-torch', os.path.join(tmp, 't.txt')])
            self.assertEqual(code, 0)
            with open(os.path.join(tmp, 't.txt')) as handle:
                self.assertIn('torch==2.9.1+cpu', handle.read())
            with open(os.path.join(tmp, 'm.txt')) as handle:
                self.assertNotIn('nvidia', handle.read())

    def test_a_bad_hash_exits_non_zero_and_writes_nothing(self):
        with tempfile.TemporaryDirectory() as tmp:
            export = os.path.join(tmp, 'export.txt')
            with open(export, 'w') as handle:
                handle.write(EXPORT)
            self.assertEqual(mq.main([export, '--torch-cpu-sha256', 'nope', '--out-main', os.path.join(tmp, 'm.txt'), '--out-torch', os.path.join(tmp, 't.txt')]), 1)
            self.assertEqual(os.listdir(tmp), ['export.txt'])


if __name__ == '__main__':
    unittest.main()
